import { describe, it, expect } from 'vitest'
import { readFileSync, existsSync } from 'fs'
import { join } from 'path'

// The icons are generated by scripts/sync-icon.mjs from build/icon-src/*.svg and
// committed. These tests catch a file that went missing or came out at the
// wrong size; they do not compare pixels (sharp output is not byte-stable
// across platforms).
const root = join(__dirname, '..', '..')
const file = (p: string): Buffer => readFileSync(join(root, p))

function pngSize(buf: Buffer): [number, number] {
  expect(buf.subarray(1, 4).toString()).toBe('PNG')
  return [buf.readUInt32BE(16), buf.readUInt32BE(20)]
}

describe('app and tray icons', () => {
  it('ships the 1024 px sources for the exe, the window and macOS', () => {
    expect(pngSize(file('build/icon.png'))).toEqual([1024, 1024])
    expect(pngSize(file('resources/icon.png'))).toEqual([1024, 1024])
  })

  it('has no stale macOS icon next to the new PNG', () => {
    // electron-builder derives the .icns from build/icon.png; an old file would win.
    expect(existsSync(join(root, 'build/icon.icns'))).toBe(false)
  })

  it('packs every size Windows asks for, including the 125 % ones (20, 40)', () => {
    const ico = file('build/icon.ico')
    const count = ico.readUInt16LE(4)
    const sizes = Array.from({ length: count }, (_, i) => ico[6 + i * 16] || 256)
    expect(sizes.sort((a, b) => a - b)).toEqual([16, 20, 24, 32, 40, 48, 64, 128, 256])
  })

  it('renders both tray states at 32 and 64 px', () => {
    for (const state of ['running', 'stopped']) {
      expect(pngSize(file(`resources/tray-${state}.png`))).toEqual([32, 32])
      expect(pngSize(file(`resources/tray-${state}@2x.png`))).toEqual([64, 64])
    }
  })

  it('draws running and stopped differently in shape, not only in colour (design rule 6)', () => {
    const svg = (s: string): string =>
      readFileSync(join(root, `build/icon-src/tray-${s}.svg`), 'utf8')
    expect(svg('running')).toContain('<line') // the needle
    expect(svg('stopped')).not.toContain('<line')
  })
})
